<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!artist_alley_ready())redirect('upgrade-artist-alley.php');$id=(int)($_GET['id']??0);$artist=artist_by_id($id);if(!$artist||!can_manage_artist($artist)){http_response_code(403);exit('You cannot manage this artist profile.');}$tab=$_GET['tab']??'overview';$allowed=['overview','profile','portfolio','commissions','requests','followers','settings'];if(!in_array($tab,$allowed,true))$tab='overview';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='save_profile'){$name=trim($_POST['artist_name']??'');if($name==='')throw new RuntimeException('Artist name is required.');$avatar=save_uploaded_image('avatar','artists/avatars',(int)$artist['user_id']);$banner=save_uploaded_image('banner','artists/banners',(int)$artist['user_id']);$sql='UPDATE artist_profiles SET artist_name=?,slug=?,headline=?,bio=?,specialties=?,website=?,commission_status=?'.($avatar?',avatar_path=?':'').($banner?',banner_path=?':'').' WHERE id=?';$args=[$name,artist_slug($name,$id),trim($_POST['headline']??''),trim($_POST['bio']??''),trim($_POST['specialties']??''),trim($_POST['website']??''),$_POST['commission_status']??'closed'];if($avatar)$args[]=$avatar;if($banner)$args[]=$banner;$args[]=$id;db()->prepare($sql)->execute($args);flash('success','Artist profile saved.');$tab='profile';}
 elseif($action==='add_portfolio'){$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Portfolio title is required.');$media=save_uploaded_image('media','artists/portfolio',(int)$artist['user_id']);db()->prepare('INSERT INTO artist_portfolio_items(artist_id,title,item_type,description,media_path,external_url,is_featured) VALUES(?,?,?,?,?,?,?)')->execute([$id,$title,$_POST['item_type']??'artwork',trim($_POST['description']??''),$media,trim($_POST['external_url']??''),isset($_POST['is_featured'])?1:0]);flash('success','Portfolio item added.');$tab='portfolio';}
 elseif($action==='delete_portfolio'){db()->prepare('DELETE FROM artist_portfolio_items WHERE id=? AND artist_id=?')->execute([(int)$_POST['item_id'],$id]);flash('success','Portfolio item removed.');$tab='portfolio';}
 elseif($action==='add_service'){$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Service title is required.');db()->prepare('INSERT INTO artist_commission_services(artist_id,title,description,price_from,turnaround_days,slots_available,is_active) VALUES(?,?,?,?,?,?,1)')->execute([$id,$title,trim($_POST['description']??''),(float)($_POST['price_from']??0),($_POST['turnaround_days']??'')!==''?(int)$_POST['turnaround_days']:null,($_POST['slots_available']??'')!==''?(int)$_POST['slots_available']:null]);flash('success','Commission service added.');$tab='commissions';}
 elseif($action==='toggle_service'){db()->prepare('UPDATE artist_commission_services SET is_active=1-is_active WHERE id=? AND artist_id=?')->execute([(int)$_POST['service_id'],$id]);flash('success','Service status updated.');$tab='commissions';}
 elseif($action==='delete_service'){db()->prepare('DELETE FROM artist_commission_services WHERE id=? AND artist_id=?')->execute([(int)$_POST['service_id'],$id]);flash('success','Commission service removed.');$tab='commissions';}
 elseif($action==='update_request'){$valid=['submitted','reviewing','accepted','in_progress','proof','completed','declined','cancelled'];$status=$_POST['status']??'';if(!in_array($status,$valid,true))throw new RuntimeException('Invalid request status.');db()->prepare('UPDATE artist_commission_requests SET status=?,artist_notes=? WHERE id=? AND artist_id=?')->execute([$status,trim($_POST['artist_notes']??''),(int)$_POST['request_id'],$id]);flash('success','Commission request updated.');$tab='requests';}
 elseif($action==='save_settings'){$status=$_POST['status']??$artist['status'];if((user()['role']??'')!=='admin')$status=$artist['status'];db()->prepare('UPDATE artist_profiles SET commission_status=?,status=?,is_featured=? WHERE id=?')->execute([$_POST['commission_status']??'closed',$status,((user()['role']??'')==='admin'&&isset($_POST['is_featured']))?1:0,$id]);flash('success','Artist settings saved.');$tab='settings';}
 }catch(Throwable $e){flash('error',$e->getMessage());}
 redirect_route('artist-alley/manage.php',['id'=>$id,'tab'=>$tab]);}
$artist=artist_by_id($id);$stats=artist_stats($id);$portfolio=artist_portfolio($id,false);$services=artist_services($id,false);$requests=artist_requests($id);$followers=artist_followers($id);app_header('Manage '.$artist['artist_name']);?>
<section class="dashboard-hero"><p class="eyebrow">ARTIST MANAGEMENT</p><h1><?=e($artist['artist_name'])?></h1><p>Build your portfolio, manage commission services, and respond to your audience.</p><p><a class="button ghost" href="view.php?slug=<?=urlencode($artist['slug'])?>">View Public Profile</a></p></section>
<nav class="management-tabs"><?php foreach(['overview'=>'Overview','profile'=>'Profile','portfolio'=>'Portfolio','commissions'=>'Commissions','requests'=>'Requests','followers'=>'Followers','settings'=>'Settings'] as $key=>$label):?><a class="<?=$tab===$key?'active':''?>" href="?id=<?=$id?>&tab=<?=$key?>"><?=e($label)?></a><?php endforeach?></nav>
<?php if($tab==='overview'):?><section class="dev-stat-grid"><article class="app-card dev-stat"><span>Portfolio works</span><strong><?=$stats['portfolio']?></strong></article><article class="app-card dev-stat"><span>Services</span><strong><?=$stats['services']?></strong></article><article class="app-card dev-stat"><span>Open requests</span><strong><?=$stats['requests']?></strong></article><article class="app-card dev-stat"><span>Followers</span><strong><?=$stats['followers']?></strong></article></section><section class="app-card"><h2>Artist status</h2><p><span class="badge"><?=e(ucfirst($artist['status']))?></span> <span class="badge"><?=e(ucfirst($artist['commission_status']))?> commissions</span></p><p><?=e($artist['headline'])?></p></section>
<?php elseif($tab==='profile'):?><section class="form-card wide"><h2>Public Artist Profile</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_profile"><label>Artist name<input name="artist_name" value="<?=e($artist['artist_name'])?>" required></label><label>Headline<input name="headline" value="<?=e($artist['headline'])?>"></label><label class="full">Biography<textarea name="bio" rows="8"><?=e($artist['bio'])?></textarea></label><label class="full">Specialties<input name="specialties" value="<?=e($artist['specialties'])?>"></label><label>Website<input type="url" name="website" value="<?=e($artist['website'])?>"></label><label>Commission status<select name="commission_status"><?php foreach(['open'=>'Open','waitlist'=>'Waitlist','closed'=>'Closed'] as $k=>$v):?><option value="<?=$k?>" <?=$artist['commission_status']===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>Replace avatar<input type="file" name="avatar" accept="image/*"></label><label>Replace banner<input type="file" name="banner" accept="image/*"></label><div class="full"><button class="button primary">Save Profile</button></div></form></section>
<?php elseif($tab==='portfolio'):?><div class="two-column-layout"><section class="app-card"><h2>Portfolio</h2><div class="portfolio-grid"><?php foreach($portfolio as $item):?><article class="portfolio-item"><?php if($item['media_path']):?><img src="<?=e(base_url($item['media_path']))?>" alt=""><?php endif?><div><h3><?=e($item['title'])?></h3><p><?=e($item['description'])?></p><form method="post" onsubmit="return confirm('Remove this portfolio item?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_portfolio"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><button class="button danger small">Remove</button></form></div></article><?php endforeach?><?php if(!$portfolio):?><p class="muted">No portfolio items yet.</p><?php endif?></div></section><aside class="app-card"><h2>Add Portfolio Work</h2><form method="post" enctype="multipart/form-data" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="add_portfolio"><label>Title<input name="title" required></label><label>Type<select name="item_type"><?php foreach(artist_portfolio_types() as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></label><label>Description<textarea name="description" rows="5"></textarea></label><label>Image<input type="file" name="media" accept="image/*"></label><label>External URL<input type="url" name="external_url"></label><label class="check-row"><input type="checkbox" name="is_featured"> Featured work</label><button class="button primary">Add Work</button></form></aside></div>
<?php elseif($tab==='commissions'):?><div class="two-column-layout"><section class="app-card"><h2>Commission Services</h2><?php foreach($services as $service):?><article class="service-card"><h3><?=e($service['title'])?></h3><p><?=e($service['description'])?></p><p><strong>$<?=number_format((float)$service['price_from'],2)?></strong> · <?=$service['is_active']?'Active':'Hidden'?></p><div class="inline-actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_service"><input type="hidden" name="service_id" value="<?=(int)$service['id']?>"><button class="button ghost small"><?=$service['is_active']?'Hide':'Activate'?></button></form><form method="post" onsubmit="return confirm('Delete this service?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_service"><input type="hidden" name="service_id" value="<?=(int)$service['id']?>"><button class="button danger small">Delete</button></form></div></article><?php endforeach?><?php if(!$services):?><p class="muted">No commission services yet.</p><?php endif?></section><aside class="app-card"><h2>Add Service</h2><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="add_service"><label>Service title<input name="title" required></label><label>Description<textarea name="description" rows="5"></textarea></label><label>Starting price<input type="number" name="price_from" min="0" step="0.01"></label><label>Turnaround days<input type="number" name="turnaround_days" min="1"></label><label>Available slots<input type="number" name="slots_available" min="0"></label><button class="button primary">Add Service</button></form></aside></div>
<?php elseif($tab==='requests'):?><section class="app-card"><h2>Commission Requests</h2><?php foreach($requests as $request):?><article class="request-card"><div><p class="eyebrow"><?=e(strtoupper($request['status']))?></p><h3><?=e($request['subject'])?></h3><p>From <?=e($request['customer_name'])?><?php if($request['budget']!==null):?> · Budget $<?=number_format((float)$request['budget'],2)?><?php endif?></p><p><?=nl2br(e($request['brief']))?></p></div><form method="post" class="stack-form request-update"><?=csrf_field()?><input type="hidden" name="action" value="update_request"><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><label>Status<select name="status"><?php foreach(['submitted','reviewing','accepted','in_progress','proof','completed','declined','cancelled'] as $status):?><option value="<?=$status?>" <?=$request['status']===$status?'selected':''?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach?></select></label><label>Private notes<textarea name="artist_notes" rows="3"><?=e($request['artist_notes'])?></textarea></label><button class="button primary small">Update</button></form></article><?php endforeach?><?php if(!$requests):?><p class="muted">No commission requests yet.</p><?php endif?></section>
<?php elseif($tab==='followers'):?><section class="app-card"><h2>Followers</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Following since</th></tr></thead><tbody><?php foreach($followers as $f):?><tr><td><?=e($f['display_name'])?></td><td><?=e($f['username'])?></td><td><?=e(date('M j, Y',strtotime($f['created_at'])))?></td></tr><?php endforeach?></tbody></table></div><?php if(!$followers):?><p class="muted">No followers yet.</p><?php endif?></section>
<?php elseif($tab==='settings'):?><section class="form-card"><h2>Artist Settings</h2><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="save_settings"><label>Commission status<select name="commission_status"><?php foreach(['open'=>'Open','waitlist'=>'Waitlist','closed'=>'Closed'] as $k=>$v):?><option value="<?=$k?>" <?=$artist['commission_status']===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><?php if((user()['role']??'')==='admin'):?><label>Approval status<select name="status"><?php foreach(['draft','pending','approved','rejected'] as $status):?><option value="<?=$status?>" <?=$artist['status']===$status?'selected':''?>><?=e(ucfirst($status))?></option><?php endforeach?></select></label><label class="check-row"><input type="checkbox" name="is_featured" <?=$artist['is_featured']?'checked':''?>> Featured artist</label><?php endif?><button class="button primary">Save Settings</button></form></section><?php endif?>
<?php app_footer();
